{"title": "二次函数交互演示", "mode": "inline", "source": "<div id="quadratic-lab" data-viz-keep>
  <style>
    #quadratic-lab {
      font-variant-numeric: tabular-nums;
      color: var(--foreground);
      padding: 2px 0 0;
    }
    #quadratic-lab .quad-kicker {
      margin: 0 0 6px;
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 600;
      letter-spacing: .08em;
      color: var(--muted-foreground);
    }
    #quadratic-lab .quad-eq-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 8px 14px;
    }
    #quadratic-lab .quad-eq {
      font-family: var(--font-mono);
      font-size: clamp(20px, 3vw, 26px);
      font-weight: 600;
      line-height: 1.3;
      color: var(--foreground);
    }
    #quadratic-lab .quad-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 3px 9px;
      border: 1px solid color-mix(in srgb, var(--primary) 26%, transparent);
      border-radius: 999px;
      background: color-mix(in srgb, var(--primary) 11%, transparent);
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 600;
      line-height: 1.4;
      color: var(--primary);
      white-space: nowrap;
    }
    #quadratic-lab .quad-badge::before {
      content: "";
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: currentColor;
      flex: none;
    }
    #quadratic-lab .quad-meta {
      margin: 5px 0 0;
      font-family: var(--font-mono);
      font-size: 12px;
      line-height: 1.55;
      color: var(--muted-foreground);
    }
    #quadratic-lab .quad-plot {
      position: relative;
      width: 100%;
      height: 330px;
      margin-top: 10px;
      animation: quad-fade-in 340ms ease-out both;
    }
    #quadratic-lab .quad-plot svg {
      display: block;
      width: 100%;
      height: 100%;
      overflow: visible;
    }
    #quadratic-lab .quad-grid-line {
      stroke: var(--viz-grid);
      stroke-width: 1;
    }
    #quadratic-lab .quad-axis-line {
      stroke: var(--viz-axis);
      stroke-width: 1.5;
    }
    #quadratic-lab .quad-tick-text {
      fill: var(--foreground);
      font-family: var(--font-mono);
      font-size: 11px;
    }
    #quadratic-lab .axis-label {
      fill: var(--viz-axis);
      font-family: var(--font-mono);
      font-size: 13px;
      font-weight: 700;
    }
    #quadratic-lab .axis-label-x { text-anchor: end; }
    #quadratic-lab .axis-label-y { text-anchor: start; }
    #quadratic-lab .quad-curve {
      fill: none;
      stroke: var(--viz-series-1);
      stroke-width: 2.25;
      stroke-linecap: round;
      stroke-linejoin: round;
    }
    #quadratic-lab .quad-sym-line {
      fill: none;
      stroke: var(--viz-axis);
      stroke-width: 1.4;
      stroke-dasharray: 4 4;
      opacity: .7;
    }
    #quadratic-lab .quad-vertex-dot {
      fill: var(--primary);
      stroke: var(--background);
      stroke-width: 2.5;
    }
    #quadratic-lab .quad-root-dot {
      fill: var(--background);
      stroke: var(--viz-series-1);
      stroke-width: 2;
    }
    #quadratic-lab .quad-point-label {
      fill: var(--foreground);
      font-family: var(--font-mono);
      font-size: 11px;
      paint-order: stroke;
      stroke: var(--background);
      stroke-width: 3px;
      stroke-linejoin: round;
    }
    #quadratic-lab .quad-controls {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px 24px;
      margin-top: 12px;
      padding-top: 14px;
      border-top: 1px solid var(--viz-grid);
    }
    #quadratic-lab .quad-control { min-width: 0; }
    #quadratic-lab .quad-ctrl-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 8px;
      margin-bottom: 3px;
    }
    #quadratic-lab .quad-ctrl-head label {
      font-family: var(--font-mono);
      font-size: 13px;
      font-weight: 600;
      color: var(--foreground);
    }
    #quadratic-lab .quad-ctrl-head output {
      font-family: var(--font-mono);
      font-size: 12px;
      color: var(--muted-foreground);
    }
    #quadratic-lab input[type="range"] {
      display: block;
      width: 100%;
      height: 22px;
      margin: 0;
      accent-color: var(--primary);
      cursor: pointer;
    }
    #quadratic-lab input[type="range"]:focus-visible {
      outline: 2px solid color-mix(in srgb, var(--primary) 55%, transparent);
      outline-offset: 3px;
      border-radius: 4px;
    }
    #quadratic-lab .quad-tip {
      margin: 10px 0 0;
      font-size: 11px;
      line-height: 1.5;
      color: var(--muted-foreground);
    }
    @keyframes quad-fade-in {
      from { opacity: 0; transform: translateY(4px); }
      to { opacity: 1; transform: none; }
    }
    @media (max-width: 560px) {
      #quadratic-lab .quad-controls { grid-template-columns: 1fr; gap: 9px; }
      #quadratic-lab .quad-plot { height: 290px; }
    }
    @media (prefers-reduced-motion: reduce) {
      #quadratic-lab .quad-plot { animation: none; }
    }
  </style>

  <p class="quad-kicker">二次函数 · 参数探索</p>
  <div class="quad-eq-row">
    <span class="quad-eq" data-viz-out="equation">y = x²</span>
    <span class="quad-badge" data-viz-out="shape">开口向上</span>
  </div>
  <p class="quad-meta" data-viz-out="readout">顶点 (0, 0) · 对称轴 x = 0 · 与 x 轴相切于 x = 0</p>

  <div class="quad-plot"><svg id="quadratic-lab-svg" role="img" aria-label="二次函数图像"></svg></div>

  <div class="quad-controls">
    <div class="quad-control">
      <div class="quad-ctrl-head"><label for="quadratic-a">a</label><output data-viz-out="a">1.0</output></div>
      <input id="quadratic-a" name="a" type="range" min="-2" max="2" step="0.1" value="1">
    </div>
    <div class="quad-control">
      <div class="quad-ctrl-head"><label for="quadratic-b">b</label><output data-viz-out="b">0.0</output></div>
      <input id="quadratic-b" name="b" type="range" min="-10" max="10" step="0.1" value="0">
    </div>
    <div class="quad-control">
      <div class="quad-ctrl-head"><label for="quadratic-c">c</label><output data-viz-out="c">0.0</output></div>
      <input id="quadratic-c" name="c" type="range" min="-10" max="10" step="0.1" value="0">
    </div>
  </div>
  <p class="quad-tip">拖动 a 改变开口方向与宽窄，b 移动对称轴，c 让图像上下平移。</p>
</div>
<script>
(function () {
  var root = document.getElementById('quadratic-lab');
  if (!root) return;
  var NS = 'http://www.w3.org/2000/svg';
  var plotEl = root.querySelector('.quad-plot');
  var svg = root.querySelector('svg');
  var entered = false;
  var last = null;
  var lastW = 0;
  var lastH = 0;
  var reduced = false;
  try {
    reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  } catch (e) {
    reduced = false;
  }

  function el(name, attrs, text) {
    var node = document.createElementNS(NS, name);
    if (attrs) {
      for (var k in attrs) {
        if (Object.prototype.hasOwnProperty.call(attrs, k) && attrs[k] !== null && attrs[k] !== undefined) {
          node.setAttribute(k, attrs[k]);
        }
      }
    }
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function round(n, d) {
    var m = Math.pow(10, d === undefined ? 1 : d);
    var v = Math.round(n * m) / m;
    return v === 0 ? 0 : v;
  }

  function fmt(n, d) {
    if (!isFinite(n)) return '—';
    var v = round(n, d === undefined ? 1 : d);
    if (Math.abs(v - Math.round(v)) < 1e-9) return String(Math.round(v));
    return v.toFixed(d === undefined ? 1 : d);
  }

  function tickNum(n) {
    var text = fmt(n, 1);
    return text.replace('-', '−');
  }

  function niceStep(span, target) {
    var raw = span / target;
    var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
    var norm = raw / mag;
    return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * mag;
  }

  function equation(a, b, c) {
    var out = 'y = ';
    if (Math.abs(a) < 1e-9) {
      if (Math.abs(b) < 1e-9) return out + tickNum(c);
      out += (b === 1 ? '' : b === -1 ? '−' : tickNum(b)) + 'x';
      if (c !== 0) out += (c > 0 ? ' + ' : ' − ') + tickNum(Math.abs(c));
      return out;
    }
    out += (a === 1 ? '' : a === -1 ? '−' : tickNum(a)) + 'x²';
    if (b !== 0) {
      out += (b > 0 ? ' + ' : ' − ') + (Math.abs(b) === 1 ? '' : tickNum(Math.abs(b))) + 'x';
    }
    if (c !== 0) out += (c > 0 ? ' + ' : ' − ') + tickNum(Math.abs(c));
    return out;
  }

  function describe(a, b, c) {
    if (Math.abs(a) < 1e-9) {
      if (Math.abs(b) < 1e-9) {
        return { shape: '常数函数', readout: c === 0 ? '图像与 x 轴重合' : '图像为一条水平直线，与 x 轴无交点' };
      }
      var lr = -c / b;
      return {
        shape: '一次函数',
        readout: '图像为直线 · 与 x 轴交于 x = ' + tickNum(lr)
      };
    }
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var disc = b * b - 4 * a * c;
    var rootText;
    if (disc > 1e-9) {
      var r1 = (-b - Math.sqrt(disc)) / (2 * a);
      var r2 = (-b + Math.sqrt(disc)) / (2 * a);
      var lo = Math.min(r1, r2);
      var hi = Math.max(r1, r2);
      rootText = '与 x 轴交于 x₁ = ' + tickNum(lo) + '，x₂ = ' + tickNum(hi);
    } else if (disc > -1e-9) {
      rootText = '与 x 轴相切于 x = ' + tickNum(h);
    } else {
      rootText = '与 x 轴无交点';
    }
    return {
      shape: a > 0 ? '开口向上' : '开口向下',
      readout: '顶点 (' + tickNum(h) + ', ' + tickNum(k) + ') · 对称轴 x = ' + tickNum(h) + ' · ' + rootText
    };
  }

  // The parabola chooses the window: vertex around 22% from the bottom (a > 0)
  // or 78% (a < 0), branches leaving near the top/bottom edge.
  function targetWindow(a, b, c) {
    if (Math.abs(a) < 1e-9) {
      var half = 4;
      var yAtA = b * -half + c;
      var yAtB = b * half + c;
      var yLo = Math.min(yAtA, yAtB);
      var yHi = Math.max(yAtA, yAtB);
      var yPad = Math.max(1, (yHi - yLo) * 0.15);
      return { xmin: -half, xmax: half, ymin: yLo - yPad, ymax: yHi + yPad };
    }
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var up = a > 0;
    var halfX;
    if (Math.abs(k) < 1e-9) {
      halfX = Math.max(1, Math.sqrt(Math.max(1, Math.abs(c)) / Math.abs(a)) * 2);
    } else {
      var edgeY = up ? k + Math.abs(k) * 2.2 : k - Math.abs(k) * 2.2;
      halfX = Math.max(2.5, Math.sqrt(Math.abs((edgeY - k) / a)) / 0.85);
    }
    var reach = Math.abs(a * halfX * halfX);
    var pad = halfX * 0.06;
    return {
      xmin: h - halfX - pad,
      xmax: h + halfX + pad,
      ymin: up ? k - reach * 0.22 : k - reach * 0.78,
      ymax: up ? k + reach * 0.78 : k + reach * 0.22
    };
  }

  function holds(win, a, b, c) {
    if (Math.abs(a) < 1e-9) return true;
    var h = -b / (2 * a);
    var k = c - b * b / (4 * a);
    var up = a > 0;
    var spanY = win.ymax - win.ymin;
    var xPad = (win.xmax - win.xmin) * 0.08;
    var yPad = spanY * 0.08;
    if (h < win.xmin + xPad || h > win.xmax - xPad) return false;
    if (k < win.ymin + yPad || k > win.ymax - yPad) return false;
    var yEdge = up ? win.ymax - yPad : win.ymin + yPad;
    var xEdge = Math.sqrt(Math.abs((yEdge - k) / a));
    if (!(h - xEdge >= win.xmin + xPad && h + xEdge <= win.xmax - xPad)) return false;
    var ideal = targetWindow(a, b, c);
    var rx = (win.xmax - win.xmin) / (ideal.xmax - ideal.xmin);
    var ry = spanY / (ideal.ymax - ideal.ymin);
    if (rx > 1.4 || rx < 0.75 || ry > 1.4 || ry < 0.75) return false;
    var vf = (k - win.ymin) / spanY;
    if (a > 0 ? (vf < 0.10 || vf > 0.40) : (vf < 0.60 || vf > 0.90)) return false;
    return true;
  }

  function chooseWindow(a, b, c, prev) {
    if (prev && Math.abs(a) > 1e-9 && holds(prev, a, b, c)) return prev;
    return targetWindow(a, b, c);
  }

  function draw(p, animate) {
    var a = p.a, b = p.b, c = p.c;
    var w = Math.max(1, Math.round(plotEl.clientWidth || 0));
    var h = Math.max(1, Math.round(plotEl.clientHeight || 0));
    lastW = w;
    lastH = h;

    if (svg.getAttribute('width') !== String(w)) {
      svg.setAttribute('width', String(w));
      svg.setAttribute('height', String(h));
      svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    } else if (svg.getAttribute('height') !== String(h)) {
      svg.setAttribute('height', String(h));
      svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var win = chooseWindow(a, b, c, last ? last.win : null);
    var padL = 46;
    var padR = 20;
    var padT = 16;
    var padB = 30;
    var iw = Math.max(20, w - padL - padR);
    var ih = Math.max(20, h - padT - padB);
    var sx = function (x) { return padL + (x - win.xmin) / (win.xmax - win.xmin) * iw; };
    var sy = function (y) { return padT + (win.ymax - y) / (win.ymax - win.ymin) * ih; };
    var plotRight = padL + iw;

    var defs = el('defs');
    var clip = el('clipPath', { id: 'quadratic-lab-clip' });
    clip.appendChild(el('rect', { x: padL, y: padT, width: iw, height: ih }));
    defs.appendChild(clip);
    svg.appendChild(defs);

    var xStep = niceStep(win.xmax - win.xmin, 9);
    var yStep = niceStep(win.ymax - win.ymin, 7);
    var xTicks = [];
    var yTicks = [];
    var x;
    var y;
    for (x = Math.ceil(win.xmin / xStep) * xStep; x <= win.xmax + 1e-9; x += xStep) xTicks.push(round(x, 6));
    for (y = Math.ceil(win.ymin / yStep) * yStep; y <= win.ymax + 1e-9; y += yStep) yTicks.push(round(y, 6));

    var grid = el('g');
    xTicks.forEach(function (tx) {
      grid.appendChild(el('line', { x1: sx(tx), y1: padT, x2: sx(tx), y2: padT + ih, class: 'quad-grid-line' }));
    });
    yTicks.forEach(function (ty) {
      grid.appendChild(el('line', { x1: padL, y1: sy(ty), x2: plotRight, y2: sy(ty), class: 'quad-grid-line' }));
    });
    svg.appendChild(grid);

    var xVisible = win.ymin <= 0 && 0 <= win.ymax;
    var yVisible = win.xmin <= 0 && 0 <= win.xmax;
    var axis = el('g');
    var xAxisY = sy(0);
    var yAxisX = sx(0);

    if (xVisible) {
      axis.appendChild(el('line', { x1: padL, y1: xAxisY, x2: plotRight, y2: xAxisY, class: 'quad-axis-line' }));
      axis.appendChild(el('path', { d: 'M' + plotRight + ',' + xAxisY + ' l-7,-3.5 v7 z', fill: 'var(--viz-axis)' }));
      axis.appendChild(el('text', { x: plotRight, y: xAxisY - 10, class: 'axis-label axis-label-x' }, 'x'));
    }
    var yLabelAnchor = 'start';
    var yLabelX = yAxisX + 10;
    if (yVisible) {
      if (yLabelX > plotRight - 14) {
        yLabelX = yAxisX - 10;
        yLabelAnchor = 'end';
      }
      axis.appendChild(el('line', { x1: yAxisX, y1: padT, x2: yAxisX, y2: padT + ih, class: 'quad-axis-line' }));
      axis.appendChild(el('path', { d: 'M' + yAxisX + ',' + padT + ' l-3.5,7 h7 z', fill: 'var(--viz-axis)' }));
      axis.appendChild(el('text', {
        x: yLabelX,
        y: padT + 14,
        class: 'axis-label axis-label-y',
        style: yLabelAnchor === 'end' ? 'text-anchor:end' : null
      }, 'y'));
    }

    function labelWidth(label) { return label.length * 6.2 + 4; }
    var lastXRight = -Infinity;
    xTicks.forEach(function (tx) {
      if (Math.abs(tx) < 1e-9) return;
      var label = tickNum(tx);
      var lw = labelWidth(label);
      var px = sx(tx);
      if (px - lw / 2 < padL - 2 || px + lw / 2 > plotRight) return;
      if (px - lw / 2 < lastXRight + 8) return;
      lastXRight = px + lw / 2;
      axis.appendChild(el('text', {
        x: px,
        y: (xVisible ? xAxisY + 16 : padT + ih + 16),
        'text-anchor': 'middle',
        class: 'quad-tick-text'
      }, label));
    });

    yTicks.forEach(function (ty) {
      if (Math.abs(ty) < 1e-9) return;
      var label = tickNum(ty);
      var ly = sy(ty) + 3.5;
      if (ly < padT + 10 || ly > padT + ih + 4) return;
      axis.appendChild(el('text', { x: padL - 7, y: ly, 'text-anchor': 'end', class: 'quad-tick-text' }, label));
    });

    if (xVisible && yVisible) {
      axis.appendChild(el('text', { x: yAxisX - 6, y: xAxisY + 16, 'text-anchor': 'end', class: 'quad-tick-text' }, '0'));
    }
    svg.appendChild(axis);

    if (Math.abs(a) > 1e-9) {
      var hv = -b / (2 * a);
      var kv = c - b * b / (4 * a);
      svg.appendChild(el('path', {
        d: 'M' + sx(hv) + ',' + padT + ' V' + (padT + ih),
        class: 'quad-sym-line',
        'clip-path': 'url(#quadratic-lab-clip)'
      }));
    }

    var curvePath = '';
    var n = Math.min(700, Math.max(160, Math.round(iw * 2)));
    for (var i = 0; i <= n; i += 1) {
      var xx = win.xmin + (win.xmax - win.xmin) * (i / n);
      var yy = a * xx * xx + b * xx + c;
      curvePath += (curvePath === '' ? 'M' : 'L') + sx(xx).toFixed(2) + ',' + sy(yy).toFixed(2);
    }
    var curve = el('path', {
      d: curvePath === '' ? 'M0,0' : curvePath,
      class: 'quad-curve',
      'clip-path': 'url(#quadratic-lab-clip)'
    });
    svg.appendChild(curve);

    if (animate && !reduced) {
      try {
        var len = curve.getTotalLength();
        curve.style.strokeDasharray = String(len);
        curve.style.strokeDashoffset = String(len);
        curve.getBoundingClientRect();
        curve.style.transition = 'stroke-dashoffset 680ms ease-out';
        curve.style.strokeDashoffset = '0';
        curve.addEventListener('transitionend', function () {
          curve.style.strokeDasharray = '';
          curve.style.strokeDashoffset = '';
          curve.style.transition = '';
        }, { once: true });
      } catch (e) {
        curve.style.strokeDasharray = '';
        curve.style.strokeDashoffset = '';
      }
    }

    if (Math.abs(a) > 1e-9) {
      var hh = -b / (2 * a);
      var kk = c - b * b / (4 * a);
      if (hh >= win.xmin && hh <= win.xmax && kk >= win.ymin && kk <= win.ymax) {
        var vx = sx(hh);
        var vy = sy(kk);
        svg.appendChild(el('circle', { cx: vx, cy: vy, r: 4.5, class: 'quad-vertex-dot' }));
        var vlabel = '顶点 (' + tickNum(hh) + ', ' + tickNum(kk) + ')';
        var vw = labelWidth(vlabel);
        var lx = vx + 9;
        var anchor = 'start';
        if (lx + vw > plotRight - 2) {
          lx = vx - 9;
          anchor = 'end';
        }
        var ly = vy - 9;
        if (ly < padT + 12) ly = vy + 18;
        svg.appendChild(el('text', {
          x: lx,
          y: ly,
          'text-anchor': anchor,
          class: 'quad-point-label'
        }, vlabel));
      }

      var disc = b * b - 4 * a * c;
      if (disc >= -1e-9) {
        var roots = disc > 1e-9 ? [(-b - Math.sqrt(disc)) / (2 * a), (-b + Math.sqrt(disc)) / (2 * a)] : [-b / (2 * a)];
        roots.forEach(function (rx, idx) {
          if (rx < win.xmin || rx > win.xmax) return;
          var dot = el('circle', { cx: sx(rx), cy: sy(0), r: 3.5, class: 'quad-root-dot' });
          dot.appendChild(el('title', null, 'x 轴交点 ' + (roots.length > 1 ? (idx === 0 ? '1' : '2') + '：' : '') + 'x = ' + tickNum(rx)));
          svg.appendChild(dot);
        });
      }
    }

    last = { a: a, b: b, c: c, win: win };
  }

  function render(raw) {
    var a = round(Number(raw.a) || 0, 1);
    var b = round(Number(raw.b) || 0, 1);
    var c = round(Number(raw.c) || 0, 1);
    var info = describe(a, b, c);
    var eq = equation(a, b, c);
    root.querySelector('[data-viz-out="equation"]').textContent = eq;
    root.querySelector('[data-viz-out="shape"]').textContent = info.shape;
    root.querySelector('[data-viz-out="readout"]').textContent = info.readout;
    svg.setAttribute('aria-label', '二次函数图像：' + eq);
