        if (lx + vw > plotRight - 2) {
          lx = vx - 9;
          anchor = 'end';
        }
        var ly = vy - 9;
        if (ly < padT + 12) ly = vy + 18;
        svg.appendChild(el('text', {
          x: lx,
          y: ly,
          'text-anchor': anchor,
          class: 'quad-point-label'
        }, vlabel));
      }

      var disc = b * b - 4 * a * c;
      if (disc >= -1e-9) {
        var roots = disc > 1e-9 ? [(-b - Math.sqrt(disc)) / (2 * a), (-b + Math.sqrt(disc)) / (2 * a)] : [-b / (2 * a)];
        roots.forEach(function (rx, idx) {
          if (rx < win.xmin || rx > win.xmax) return;
          var dot = el('circle', { cx: sx(rx), cy: sy(0), r: 3.5, class: 'quad-root-dot' });
          dot.appendChild(el('title', null, 'x 轴交点 ' + (roots.length > 1 ? (idx === 0 ? '1' : '2') + '：' : '') + 'x = ' + tickNum(rx)));
          svg.appendChild(dot);
        });
      }
    }

    last = { a: a, b: b, c: c, win: win };
  }

  function render(raw) {
    var a = round(Number(raw.a) || 0, 1);
    var b = round(Number(raw.b) || 0, 1);
    var c = round(Number(raw.c) || 0, 1);
    var info = describe(a, b, c);
    var eq = equation(a, b, c);
    root.querySelector('[data-viz-out="equation"]').textContent = eq;
    root.querySelector('[data-viz-out="shape"]').textContent = info.shape;
    root.querySelector('[data-viz-out="readout"]').textContent = info.readout;
    svg.setAttribute('aria-label', '二次函数图像：' + eq);
    draw({ a: a, b: b, c: c }, !entered);
    entered = true;
    return { a: fmt(a, 1), b: fmt(b, 1), c: fmt(c, 1) };
  }

  dshViz.bind('#quadratic-lab', render);

  if (typeof ResizeObserver === 'function') {
    var ro = new ResizeObserver(function () {
      if (!last) return;
      var w = Math.round(plotEl.clientWidth || 0);
      var h = Math.round(plotEl.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw({ a: last.a, b: last.b, c: last.c }, false);
    });
    ro.observe(plotEl);
  }
})();
</script>"}
